def find_max(nums):
    if not nums:
        raise ValueError("empty list")
    best = nums[0]  # not 0: all may be < 0
    for x in nums:
        if x > best:
            best = x
    return best

print(find_max([3, -2, 9, 4]))   # 9
print(find_max([-7, -3, -5]))    # -3

def factorial(n):
    if n <= 1:          # base case
        return 1
    # recursive case: a smaller input
    return n * factorial(n - 1)

print(factorial(5))   # 120

def merge_sort(items):
    if len(items) <= 1:
        return items          # base case
    mid = len(items) // 2
    left = merge_sort(items[:mid])
    right = merge_sort(items[mid:])
    merged, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        # <= takes left on ties: stable
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    return merged + left[i:] + right[j:]

