def bfs_distances(start):
    dist = {start: 0}  # also "visited"
    queue = deque([start])
    while queue:
        node = queue.popleft()  # oldest
        for nxt in graph[node]:
            if nxt not in dist:  # mark now
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

def dfs(node, seen, order):
    seen.add(node)
    order.append(node)
    for nxt in graph[node]:
        if nxt not in seen:
            dfs(nxt, seen, order)  # go deep
    return order

